    n = len(nums)
    tree = [0] * (n + 1)
    cur = [0] * n
    def add(i, d):
        i += 1
        while i <= n:
            tree[i] += d
            i += i & -i
    def prefix(i):
        s = 0
        i += 1
        while i > 0:
            s += tree[i]
            i -= i & -i
        return s
    for i, v in enumerate(nums):
        cur[i] = v
        add(i, v)
    out = []
    for op in ops:
        if op[0] == 'update':
            add(op[1], op[2] - cur[op[1]])
            cur[op[1]] = op[2]
